package dev.localllm.harness.application.dto.result;

import java.time.Duration;

import dev.localllm.harness.application.model.TurnStatus;

/**
 * Summary of a finished model turn.
 *
 * @param content answer text
 * @param status how the turn ended
 * @param promptTokens tokens of the prompt processed by the model
 * @param completionTokens tokens generated by the model, including thinking
 * @param elapsed wall-clock duration of the turn
 */
public record TurnResult(
    String content,
    TurnStatus status,
    int promptTokens,
    int completionTokens,
    Duration elapsed) {
}
